pub const SHAPE:[i16;9]=[0,-1,1,-17,-16,-15,15,16,17];
const OFFSETS:[[i16;2];12]=[[0,-48],[32,-32],[48,0],[32,32],[0,48],[-32,32],[-48,0],[-32,-32],[-12,-4],[-7,-4],[-1,6],[-2,14]];
#[derive(Clone,Copy,Debug,Default,PartialEq,Eq)]pub struct Unit{pub slot:u8,pub position:[i16;2],pub class:u8,pub phase:u8,pub flags31:u8,pub role:i8,pub group:u8,pub heading:u8,pub hardware17:u8}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct Bounds{pub left:i16,pub right:i16,pub top:i16,pub bottom:i16}
impl Bounds{pub fn actor(p:[i16;2])->Self{Self{left:p[0],right:p[0].wrapping_add(15),top:p[1],bottom:p[1].wrapping_add(15)}}fn contains(self,p:[i16;2])->bool{self.left<=p[0]&&p[0]<=self.right&&self.top<=p[1]&&p[1]<=self.bottom}
 ///431ee0's output arguments are component lengths, not coordinates.
 ///432250 overwrites three of45bf90's four shared rectangle globals.
 pub fn ray(&mut self,a:[i16;2],b:[i16;2]){let x=(b[0]>>4).wrapping_sub(a[0]>>4);let y=(b[1]>>4).wrapping_sub(a[1]>>4);self.left=if x<0{x.wrapping_neg()}else{x};self.top=if y<0{y.wrapping_neg()}else{y};self.right=0;}}
pub fn query(buckets:&[Vec<usize>;256],bucket:u8)->Vec<u8>{let(mut out,mut count)=(Vec::new(),0i16);for d in SHAPE{let cell=i16::from(bucket).wrapping_add(d)as u16;if cell<256{let b=&buckets[usize::from(cell)];if !b.is_empty(){count=count.wrapping_add(b.len()as i16);if count<288{out.extend(b.iter().map(|&n|n as u8));}}}}out}
pub trait World{type Error;fn unit(&mut self,slot:u8)->Result<Unit,Self::Error>;fn task(&mut self,group:u8)->Result<i8,Self::Error>;fn mark(&mut self,group:u8,value:u8)->Result<(),Self::Error>;fn random(&mut self)->u32;fn ray(&mut self,start:[i16;2],target:[i16;2])->Result<bool,Self::Error>;fn line(&mut self,slot:u8,target:[i16;2])->Result<(),Self::Error>;fn layout(&mut self,group:u8,value:u8)->Result<(),Self::Error>;fn peer(&mut self,slot:u8,peer:u8)->Result<(),Self::Error>;}
///45bbc0 consumes one draw only after phase/W17 admission. Its offset index
///advances BOTH the wrapped heading and the unwrapped candidate ordinal.
pub fn yield_to<W:World>(actor:u8,peer:u8,bounds:&mut Bounds,w:&mut W)->Result<(),W::Error>{let a=w.unit(actor)?;let p=w.unit(peer)?;if !matches!(p.phase,9|58)||a.hardware17&1==0||p.hardware17&1!=0{return Ok(());}let first=((w.random()as u16%5)as u8).wrapping_sub(2).wrapping_add(a.heading);for i in 0..5usize{let offset=OFFSETS[usize::from(first.wrapping_add(i as u8)&7)+i];let target=std::array::from_fn(|j|p.position[j].wrapping_add(offset[j]));bounds.ray(p.position,target);if w.ray(p.position,target)?{w.line(peer,target)?;w.layout(p.group,4)?;w.peer(peer,actor)?;break;}}Ok(())}
///45bf90; the passed list is44cd60's cached membership, with live UNIT data.
///Neither fresh active filtering nor one-call-per-overlap deduplication occurs.
pub fn run<W:World>(actor:u8,candidates:&[u8],single_player:bool,w:&mut W)->Result<Bounds,W::Error>{let a=w.unit(actor)?;let mut bounds=Bounds::actor(a.position);for &slot in candidates{let p=w.unit(slot)?;if p.class==2{continue;}let mut task=-1;if single_player&&p.role!=0{w.mark(p.group,0)?;if p.flags31&3==1&&p.flags31&4!=0{w.mark(p.group,1)?;task=w.task(p.group)?;}}if slot==actor||matches!(task,1|3)||matches!(p.phase,23|46|24|47)||(p.flags31^a.flags31)&3!=0{continue;}let[x,y]=p.position;for corner in [[x,y],[x.wrapping_add(15),y],[x.wrapping_add(15),y.wrapping_add(15)],[x,y.wrapping_add(15)]]{if bounds.contains(corner){yield_to(actor,slot,&mut bounds,w)?;}}}Ok(bounds)}
///45bec0's actual gate.45c210 calls it only after its opposite team test;
///the executed natural caller therefore cannot reach45bd30 on stable fields.
pub fn road_yield_admitted(near_codes:[u8;5],actor_flags31:u8,hardware_flags31:u8,actor_heading:u8,hardware_heading:u8,leader7:i8,movement7:u8)->bool{near_codes.into_iter().any(|c|c&127==7)&&(actor_flags31^hardware_flags31)&3==0&&actor_heading==hardware_heading&&i16::from(leader7>>4)<=i16::from(movement7>>4)}

